// Generated by vibelang from src/server/openCode2Catalog.vibe; the migrate flow writes it again with each batch.
import * as Option from "effect/Option";
import * as Effect from "effect/Effect";
import * as OpenCodeRuntime from "./OpenCodeRuntime.js";
// Cold catalogs take seconds; model reads already retry empty catalogs.
const PROVIDER_NAME_TIMEOUT = "3 seconds";
/** Provider names are optional decoration; bound their read so models cannot stall. */
export const loadOpenCode2Catalog = (client, directory) => {
    const location = { directory };
    return Effect.mapError(Effect.map(Effect.all({
        models: client.model.list({ location }),
        providers: Effect.option(Effect.timeout(client.provider
            .list({ location }), PROVIDER_NAME_TIMEOUT)),
    }, { concurrency: "unbounded" }), ({ models, providers }) => {
        const providerNames = new Map((Option.getOrUndefined(providers)?.data ?? []).map((provider) => [
            provider.id,
            provider.name,
        ]));
        return models.data.map((model) => {
            const providerName = providerNames.get(model.providerID);
            return {
                providerID: model.providerID,
                id: model.id,
                name: model.name,
                ...(providerName ? { providerName } : {}),
                variants: model.variants.map((variant) => ({ id: variant.id })),
                family: model.family,
                released: model.time.released,
                deprecated: model.status === "deprecated",
            };
        });
    }), (cause) => new OpenCodeRuntime.OpenCodeRuntimeError({
        operation: "model.list",
        detail: "The OpenCode server could not list its models.",
        cause,
    }));
};
